import{_ as n,C as i,o as d,c as l,j as r,a,E as o,a2 as s}from"./chunks/framework.BxGh02fV.js";const q=JSON.parse('{"title":"Registre des évolutions","description":"","frontmatter":{"title":"Registre des évolutions"},"headers":[],"relativePath":"agent/evolutions.md","filePath":"agent/evolutions.md"}'),c={name:"agent/evolutions.md"};function u(f,e,v,p,m,h){const t=i("Ask");return d(),l("div",null,[e[0]||(e[0]=r("h1",{id:"registre-des-evolutions",tabindex:"-1"},[a("Registre des évolutions "),r("a",{class:"header-anchor",href:"#registre-des-evolutions","aria-label":'Permalink to "Registre des évolutions"'},"​")],-1)),e[1]||(e[1]=r("p",null,"Le registre garde tout ce qui mérite d'être retenu sans être traité tout de suite : un défaut croisé en passant, une idée, une amélioration, une découverte. Vous venez ici pour que l'agent note ces choses, les trie, puis décide avec vous de leur sort.",-1)),e[2]||(e[2]=r("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[a("Ce que vous demandez à l'agent "),r("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),o(t,{say:"Note une anomalie : l'export plante quand le nom contient une apostrophe.",verb:"effortless_evolution_add",family:"evolutions",args:'{"type":"Anomalie","title":"L’export plante quand le nom contient une apostrophe"}'}),o(t,{say:"Ajoute une idée d'amélioration : un mode sombre pour l'écran Release.",verb:"effortless_evolution_add",family:"evolutions",args:'{"type":"Amélioration","title":"Mode sombre pour l’écran Release"}'}),o(t,{say:"Passe l'évolution EVO-041 en criticité 1 et priorité 2.",verb:"effortless_evolution_edit",family:"evolutions",args:'{"evo_id":"EVO-041","criticality":"1","priority":"2"}'}),o(t,{say:"Par quoi je reprends ? Montre-moi la file.",verb:"effortless_evolution_queue",family:"evolutions"}),o(t,{say:"Transforme l'évolution EVO-041 en épic dans la zone Données.",verb:"effortless_evolution_graduate",family:"evolutions",args:'{"evo_id":"EVO-041","zone":"Données"}'}),o(t,{say:"L'évolution EVO-041 est traitée : résous-la, c'est réglé par le correctif de l'export.",verb:"effortless_evolution_resolve",family:"evolutions",args:'{"evo_id":"EVO-041","note":"Réglé par le correctif de l’export"}'}),o(t,{say:"Retire EVO-041, on ne le fera pas : le client a changé d'avis.",verb:"effortless_evolution_retire",family:"evolutions",args:'{"evo_id":"EVO-041","reason":"Le client a changé d’avis"}'}),o(t,{say:"EVO-041 ne peut démarrer qu'après la clôture de l'épic 12.",verb:"effortless_evolution_depends_on",family:"evolutions",args:'{"evo_id":"EVO-041","target":"12"}'}),e[3]||(e[3]=s('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="noter-une-evolution" tabindex="-1">Noter une évolution <a class="header-anchor" href="#noter-une-evolution" aria-label="Permalink to &quot;Noter une évolution&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/evolutions.html#evolution-add"><code>effortless_evolution_add</code></a> consigne l&#39;entrée. Le <code>type</code> est l&#39;un de cinq marqueurs : <code>Découverte</code>, <code>Fonctionnalité</code>, <code>Amélioration</code>, <code>Anomalie</code> ou <code>Test</code>. L&#39;agent passe aussi le <code>title</code>, et si besoin :</p><ul><li><code>detail</code> : le texte complet ;</li><li><code>reporter</code> : qui rapporte l&#39;entrée ;</li><li><code>criticality</code> et <code>priority</code> : des entiers de 1 à 3, 1 étant le plus urgent. Sans eux, l&#39;entrée reste <strong>non classée</strong> ;</li><li><code>status</code> : <code>Planifié</code> par défaut. Pour un type donné (hors <code>Anomalie</code>), si le quota d&#39;entrées actives est atteint, l&#39;entrée est posée <code>En Attente</code> ;</li><li><code>born_marker</code> : un fragment de texte stable qui nomme le défaut dans le code suivi par git. Pendant un chantier, le moteur vérifie alors si le défaut existait avant la story. S&#39;il est né de ce travail, l&#39;entrée est refusée : on le corrige dans le chantier.</li></ul><p>La réponse porte une <code>implication</code> : des verbes suggérés. L&#39;agent ne les déclenche jamais tout seul.</p><h3 id="lire-et-trier" tabindex="-1">Lire et trier <a class="header-anchor" href="#lire-et-trier" aria-label="Permalink to &quot;Lire et trier&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-list"><code>effortless_evolution_list</code></a> : lecture seule. Filtres facultatifs : <code>status</code> (<code>Planifié</code>, <code>En cours</code>, <code>En Attente</code>, <code>Résolu</code>, <code>Retiré</code>), <code>query</code> (recherche sans tenir compte de la casse dans l&#39;identifiant, le titre et le détail) et <code>form</code> (<code>full</code> ou <code>compact</code>).</li><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-queue"><code>effortless_evolution_queue</code></a> : lecture seule. La file des entrées actives, déjà triées par le moteur : d&#39;abord celles dont la dépendance n&#39;attend plus, puis criticité, priorité, ancienneté, identifiant. Elle répond à « par quoi reprendre ». <code>limit</code> borne la fenêtre (25 par défaut, 200 au plus) ; le total est rendu à côté.</li></ol><h3 id="qualifier" tabindex="-1">Qualifier <a class="header-anchor" href="#qualifier" aria-label="Permalink to &quot;Qualifier&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-edit"><code>effortless_evolution_edit</code></a> : corrige <code>criticality</code>, <code>priority</code> et <code>detail</code>. L&#39;ancien texte du détail est conservé, jamais écrasé. Marche aussi sur une entrée déjà résolue ou retirée. Ne touche ni au titre, ni au statut, ni au type.</li><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-requalify"><code>effortless_evolution_requalify</code></a> : fait passer une entrée de <code>Anomalie</code> à <code>Amélioration</code>, ou l&#39;inverse, et rien d&#39;autre. L&#39;identifiant ne change pas.</li><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-set-ready"><code>effortless_evolution_set_ready</code></a> : pose ou lève le drapeau « prête à être promue » (<code>ready</code>).</li></ol><h3 id="ordonner-par-dependance" tabindex="-1">Ordonner par dépendance <a class="header-anchor" href="#ordonner-par-dependance" aria-label="Permalink to &quot;Ordonner par dépendance&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/evolutions.html#evolution-depends-on"><code>effortless_evolution_depends_on</code></a> déclare qu&#39;une évolution (<code>evo_id</code>) attend la clôture d&#39;une autre évolution ou d&#39;un épic (<code>target</code>). Elle passe derrière dans la file tant que la cible n&#39;est pas close, sans être retirée ni décomptée. Sans <code>target</code>, la dépendance est levée.</p><h3 id="promouvoir-en-epic" tabindex="-1">Promouvoir en épic <a class="header-anchor" href="#promouvoir-en-epic" aria-label="Permalink to &quot;Promouvoir en épic&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/evolutions.html#evolution-graduate"><code>effortless_evolution_graduate</code></a> rattache l&#39;évolution à un épic existant (<code>epic_id</code>) ou en crée un et l&#39;active à partir d&#39;une <code>zone</code> (avec <code>title</code> et <code>description</code> facultatifs). Il ne crée aucune story : c&#39;est l&#39;étape suivante (<a href="/Effortless/agent/piloter.html">Piloter le travail</a>).</p><h3 id="clore-sans-passer-par-un-epic" tabindex="-1">Clore sans passer par un épic <a class="header-anchor" href="#clore-sans-passer-par-un-epic" aria-label="Permalink to &quot;Clore sans passer par un épic&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-resolve"><code>effortless_evolution_resolve</code></a> : résout l&#39;évolution. La <code>note</code>, qui dit ce qui l&#39;a réglée, est obligatoire.</li><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-retire"><code>effortless_evolution_retire</code></a> : l&#39;écarte explicitement (statut <code>Retiré</code>). Le <code>reason</code> est obligatoire. Marche même sur une évolution déjà promue en épic ; ne pose jamais <code>Résolu</code>.</li></ol><h3 id="mettre-a-niveau-un-ancien-registre" tabindex="-1">Mettre à niveau un ancien registre <a class="header-anchor" href="#mettre-a-niveau-un-ancien-registre" aria-label="Permalink to &quot;Mettre à niveau un ancien registre&quot;">​</a></h3><p>Deux verbes servent une seule fois, sur un registre hérité d&#39;une version antérieure. Ils sont rejouables sans effet de bord.</p><ol><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-migrate-markers"><code>effortless_evolution_migrate_markers</code></a> : convertit l&#39;ancien champ <code>type</code> (finding, besoin, amélioration, refonte, chantier) vers l&#39;un des cinq marqueurs. Aucun identifiant ne change.</li><li><a href="/Effortless/reference/mcp/evolutions.html#evolution-migrate-levels"><code>effortless_evolution_migrate_levels</code></a> : convertit en entiers les niveaux écrits à la main. Sa réponse nomme chaque valeur qu&#39;il n&#39;a pas su convertir.</li></ol><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>Le registre dans l&#39;écran <a href="/Effortless/guide/backlog.html">Backlog</a>, racine <strong>Registre</strong>, onglet <strong>Registre des évolutions</strong> : identifiant, <strong>Type</strong>, titre, <strong>État</strong>, <strong>Criticité</strong>, <strong>Priorité</strong>, avec la recherche et les filtres <strong>Marqueur</strong> et <strong>Masquer Résolu/Retiré</strong>.</li><li>Le même registre rendu en Markdown dans <code>blueprints/4-Evolutions.md</code>.</li><li>Une évolution promue devient un épic visible dans le Backlog, sous <strong>Projet</strong>.</li><li>À la clôture d&#39;un épic, les évolutions qu&#39;il laisse <strong>En cours</strong> sont nommées : elles ne se résolvent pas toutes seules.</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Marqueur de <code>type</code> hors des cinq</td><td><code>cadrage:markerInvalid</code></td><td>Passer <code>Découverte</code>, <code>Fonctionnalité</code>, <code>Amélioration</code>, <code>Anomalie</code> ou <code>Test</code>.</td></tr><tr><td><code>status</code> hors nomenclature</td><td><code>cadrage:statusInvalid</code></td><td>Passer <code>Planifié</code>, <code>En cours</code>, <code>En Attente</code>, <code>Résolu</code> ou <code>Retiré</code>.</td></tr><tr><td><code>criticality</code> ou <code>priority</code> hors de 1 à 3</td><td><code>cadrage:levelOutOfRange</code></td><td>Passer un entier de 1 à 3, ou omettre le champ pour laisser l&#39;entrée non classée.</td></tr><tr><td>Anomalie déposée alors qu&#39;elle est née du chantier en cours</td><td><code>cadrage:evolutionNeeDuChantier</code></td><td>La corriger dans le chantier : <code>task_add</code> ouvre la tâche qui la porte.</td></tr><tr><td>Identifiant d&#39;évolution inconnu</td><td><code>cadrage:evolutionUnknown</code> (ou <code>cadrage:evolutionNotFound</code> pour <code>graduate</code>)</td><td>Lire le registre avec <code>evolution_list</code> et reprendre le bon identifiant.</td></tr><tr><td><code>form</code> autre que <code>full</code> ou <code>compact</code></td><td><code>cadrage:evolutionSearchFormInvalide</code></td><td>Passer <code>full</code> ou <code>compact</code>.</td></tr><tr><td><code>evolution_edit</code> sans aucun champ</td><td><code>cadrage:evolutionEditEmpty</code></td><td>Passer au moins <code>criticality</code>, <code>priority</code> ou <code>detail</code>.</td></tr><tr><td>Résoudre, retirer ou marquer prête une évolution déjà <code>Résolu</code> ou <code>Retiré</code></td><td><code>cadrage:evolutionAlreadyTerminal</code></td><td>Rien à lever : un statut terminal ne se modifie plus. Ouvrir une entrée neuve si le sujet revient.</td></tr><tr><td>Requalifier autre chose que Anomalie vers Amélioration, ou l&#39;inverse</td><td><code>cadrage:requalifyNotAllowed</code></td><td>Retirer l&#39;entrée, puis en ouvrir une du bon marqueur.</td></tr><tr><td>Retirer sans motif</td><td><code>cadrage:evolutionRetireReasonRequired</code></td><td>Passer <code>reason</code>.</td></tr><tr><td>Résoudre sans raison</td><td><code>cadrage:evolutionResolveNoteRequired</code></td><td>Passer <code>note</code>.</td></tr><tr><td>Dépendance qui ferme un cycle, ou d&#39;une évolution envers elle-même</td><td><code>cadrage:dependencyCycle</code></td><td>Choisir une autre cible.</td></tr><tr><td>Dépendance vers une évolution inexistante</td><td><code>cadrage:dependencyUnknown</code></td><td>Vérifier l&#39;identifiant avec <code>evolution_list</code>.</td></tr><tr><td>Cible de dépendance qui n&#39;est ni une évolution ni un épic</td><td><code>cadrage:dependencyUnknownShape</code></td><td>Passer l&#39;identifiant d&#39;une évolution ou d&#39;un épic.</td></tr></tbody></table>',22))])}const _=n(c,[["render",u]]);export{q as __pageData,_ as default};
